//! Retry configuration.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct RetryConfig {
    /// Total attempts allowed, including the first call. Must be >= 1.
    pub max_attempts: u32,
    /// Base delay before the first retry, in milliseconds.
    pub base_delay_ms: u64,
    /// Maximum delay between retries, in milliseconds.
    pub max_delay_ms: u64,
}

impl RetryConfig {
    /// Returns the delay for a retry at `retry_index` (zero-based).
    pub fn delay_for_retry(&self, retry_index: u32) -> u64 {
        let delay = self
            .base_delay_ms
            .checked_mul(2u64.saturating_pow(retry_index))
            .unwrap_or(u64::MAX);
        delay.min(self.max_delay_ms)
    }
}

#[cfg(test)]
mod tests {
    use super::RetryConfig;

    #[test]
    fn delay_is_exponential_and_bounded() {
        let config = RetryConfig {
            max_attempts: 6,
            base_delay_ms: 10,
            max_delay_ms: 25,
        };

        assert_eq!(config.delay_for_retry(0), 10);
        assert_eq!(config.delay_for_retry(1), 20);
        assert_eq!(config.delay_for_retry(2), 25);
        assert_eq!(config.delay_for_retry(10), 25);
    }
}

mod config;
mod error;
mod sleeper;

pub use config::RetryConfig;
pub use error::RetryError;
pub use sleeper::{FakeSleeper, Sleeper};

/// Runs `job` until it succeeds or the retry budget is exhausted.
/// The public signature is frozen; do not change it.
pub fn run_job(
    config: &RetryConfig,
    sleeper: &mut dyn Sleeper,
    mut job: impl FnMut() -> Result<(), RetryError>,
) -> Result<(), RetryError> {
    // `max_attempts` includes the initial call. A zero value is treated as
    // one attempt so the runner always invokes the job at least once.
    let max_attempts = config.max_attempts.max(1);

    for attempt in 0..max_attempts {
        match job() {
            Ok(()) => return Ok(()),
            Err(error) if error.is_transient() && attempt + 1 < max_attempts => {
                sleeper.sleep_ms(config.delay_for_retry(attempt));
            }
            Err(error) => return Err(error),
        }
    }
    unreachable!("max_attempts is clamped to at least one")
}

#[cfg(test)]
mod tests {
    use super::{run_job, FakeSleeper, RetryConfig, RetryError};

    fn config(max_attempts: u32) -> RetryConfig {
        RetryConfig {
            max_attempts,
            base_delay_ms: 10,
            max_delay_ms: 25,
        }
    }

    #[test]
    fn retries_transient_errors_until_success() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            if calls < 3 {
                Err(RetryError::Transient("temporary".into()))
            } else {
                Ok(())
            }
        });

        assert_eq!(result, Ok(()));
        assert_eq!(calls, 3);
        assert_eq!(sleeper.sleeps, vec![10, 20]);
    }

    #[test]
    fn permanent_errors_return_without_retry() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Permanent("invalid".into()))
        });

        assert_eq!(result, Err(RetryError::Permanent("invalid".into())));
        assert_eq!(calls, 1);
        assert!(sleeper.sleeps.is_empty());
    }

    #[test]
    fn attempt_limit_includes_first_call_and_delays_are_bounded() {
        let mut sleeper = FakeSleeper::default();
        let mut calls = 0;

        let result = run_job(&config(4), &mut sleeper, || {
            calls += 1;
            Err(RetryError::Transient("down".into()))
        });

        assert_eq!(result, Err(RetryError::Transient("down".into())));
        assert_eq!(calls, 4);
        assert_eq!(sleeper.sleeps, vec![10, 20, 25]);
    }
}

//! Error taxonomy for the job runner.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum RetryError {
    /// Transient faults may be retried (network blips, temporary locks).
    Transient(String),
    /// Permanent faults must return immediately (bad input, missing job).
    Permanent(String),
}

impl RetryError {
    /// Whether this error is eligible for another attempt.
    pub fn is_transient(&self) -> bool {
        matches!(self, Self::Transient(_))
    }
}

use jobrunner::{run_job, FakeSleeper, RetryConfig, RetryError};

#[test]
fn public_api_retries_transient_failures_and_stops_on_success() {
    let config = RetryConfig {
        max_attempts: 3,
        base_delay_ms: 5,
        max_delay_ms: 8,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        match calls {
            1 => Err(RetryError::Transient("temporary".into())),
            2 => Err(RetryError::Transient("still temporary".into())),
            _ => Ok(()),
        }
    });
    assert_eq!(result, Ok(()));
    assert_eq!(calls, 3);
    assert_eq!(sleeper.sleeps, vec![5, 8]);
}

#[test]
fn public_api_does_not_retry_permanent_failures() {
    let config = RetryConfig {
        max_attempts: 10,
        base_delay_ms: 1,
        max_delay_ms: 2,
    };
    let mut sleeper = FakeSleeper::default();
    let mut calls = 0;
    let result = run_job(&config, &mut sleeper, || {
        calls += 1;
        Err(RetryError::Permanent("bad input".into()))
    });
    assert_eq!(result, Err(RetryError::Permanent("bad input".into())));
    assert_eq!(calls, 1);
    assert!(sleeper.sleeps.is_empty());
}
